-- =============================================================================
-- 0130 — Importação do universo de marcas da Groscove (07/11/2026): 259 marcas únicas a partir de 5 fontes (Lista
-- oficial de 199 marcas, planilha de sites/telefones/e-mails oficiais, planilha interna de anunciantes e comissões,
-- Banco de marcas e a planilha de anunciantes com código MID). Sem duplicar: nomes iguais escritos de jeitos
-- diferentes viraram uma marca só (Boticário = O Boticário, CiaHering = Hering = Cia Hering, Multi = Multilaser…).
-- Ficaram de fora, por decisão do responsável: BBB e Groscove 28, e as 9 marcas a confirmar (Boost Game, Care Beauty,
-- Casa Independente, Icare, Just For You, Verde, Kings, Tiger, Lojas REDE).
--
-- Cada marca: nome, categoria, site oficial, domínios de e-mail corporativo; ligada à Groscove, aprovada e fora da
-- vitrine pública (status 'inactive'). Dados internos (CPA, CPA Influencer, MID, telefone e e-mail oficiais) em
-- brand_internal. Idempotente: marca que já existe (mesmo nome comparável) não é recriada. Tudo editável pela Groscove.
-- Os logos entram na migração seguinte (0131), depois de baixados e conferidos.
-- =============================================================================
create or replace function public.groscove_brands_import(p_rows jsonb)
returns int language plpgsql security definer set search_path = '' as $$
declare r jsonb; v_id uuid; v_g uuid := public.groscove_agency_id(); v_n int := 0;
begin
  for r in select * from jsonb_array_elements(p_rows) loop
    select b.id into v_id from public.brands b where public.brand_name_key(b.name) = public.brand_name_key(r ->> 'name') and not b.is_demo limit 1;
    if v_id is null then
      insert into public.brands (slug, name, site_url, status, default_relationship, is_demo, approval_status, category, email_domains)
      values (public.free_slug(r ->> 'slug', 'brand'), r ->> 'name', r ->> 'site_url', 'inactive', 'sponsor', false, 'approved', r ->> 'category',
              coalesce((select array_agg(x) from jsonb_array_elements_text(r -> 'email_domains') x), '{}'))
      returning id into v_id;
      v_n := v_n + 1;
    else
      update public.brands set category = coalesce(category, r ->> 'category'),
        email_domains = case when cardinality(email_domains) = 0 then coalesce((select array_agg(x) from jsonb_array_elements_text(r -> 'email_domains') x), '{}') else email_domains end
      where id = v_id;
    end if;
    if v_g is not null and not exists (select 1 from public.agency_brands ab where ab.brand_id = v_id and ab.status = 'active') then
      insert into public.agency_brands (agency_id, brand_id, status) values (v_g, v_id, 'active')
      on conflict (agency_id, brand_id) do update set status = 'active';
    end if;
    insert into public.brand_internal (brand_id, cpa, cpa_influencer, mid, official_phone, official_email)
    values (v_id, nullif(r ->> 'cpa', ''), nullif(r ->> 'cpa_influencer', ''), nullif(r ->> 'mid', ''), nullif(r ->> 'phone', ''), nullif(lower(r ->> 'email'), ''))
    on conflict (brand_id) do nothing;
  end loop;
  return v_n;
end $$;
revoke execute on function public.groscove_brands_import(jsonb) from public, anon, authenticated;
grant execute on function public.groscove_brands_import(jsonb) to service_role;

